package com.thingsbook.library;
import android.content.Context;import android.webkit.WebResourceResponse;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Fixed-origin EAPI adapter. No password persistence, mirror scanning or challenge bypass. */
final class ZLibraryProvider{
 static final String DOMAIN="https://z-lib.gd";static final int MAX=32*1024*1024;private final ProviderSecrets secrets;private long epoch=0;private boolean running=false;private volatile HttpURLConnection connection;private final Map<String,Ticket> tickets=new HashMap<>();
 private static final class Ticket{String url;long epoch,expires;Ticket(String u,long g){url=u;epoch=g;expires=System.currentTimeMillis()+60000;}}
 ZLibraryProvider(Context context){secrets=new ProviderSecrets(context);}
 static boolean fileAllowed(String value){try{URI u=new URI(value);String h=u.getHost();if(!"https".equals(u.getScheme())||u.getPort()!=-1||u.getUserInfo()!=null||u.getFragment()!=null||value.length()>8192||h==null)return false;if("dln1.ncdn.ec".equals(h))return true;for(String host:new String[]{"z-lib.gd","zlibcdn.com","booksdl.org"})if(h.equals(host)||h.endsWith("."+host))return true;return false;}catch(Exception e){return false;}}
 static String reference(JSONObject value)throws Exception{String id=value.optString("id"),hash=value.optString("hash");if(!id.matches("\\d{1,12}")||!hash.matches("[a-zA-Z0-9]{1,128}"))throw new IOException("Invalid book reference.");return id+"/"+hash;}
 static boolean validSession(JSONObject s){if(s==null||s.optInt("version")!=1||!DOMAIN.equals(s.optString("domain")))return false;JSONObject c=s.optJSONObject("cookies");return c!=null&&c.optString("remix_userid").matches("\\d{1,30}")&&c.optString("remix_userkey").matches("[a-zA-Z0-9._~+/=-]{1,4096}");}
 synchronized long generation(){return epoch;}
 synchronized void cancel(){epoch++;tickets.clear();if(connection!=null)connection.disconnect();}
 private synchronized void fresh(long generation)throws IOException{if(generation!=epoch)throw new IOException("Request cancelled.");}
 private JSONObject session()throws Exception{byte[] raw=secrets.read();if(raw==null)return null;try{JSONObject s=new JSONObject(new String(raw,StandardCharsets.UTF_8));if(!validSession(s))throw new IOException("The protected provider session could not be opened.");return s;}finally{Arrays.fill(raw,(byte)0);}}
 private synchronized void save(JSONObject s,long generation)throws Exception{fresh(generation);if(!validSession(s))throw new IOException("Unsupported provider session.");byte[] raw=s.toString().getBytes(StandardCharsets.UTF_8);try{secrets.write(raw);}finally{Arrays.fill(raw,(byte)0);}}
 private byte[] request(String value,String fields,JSONObject session,boolean download,long generation)throws Exception{
  long deadline=System.currentTimeMillis()+45000;
  for(int hop=0;hop<5;hop++){
   fresh(generation);URL url=new URL(value);if(download?!fileAllowed(value):!value.startsWith(DOMAIN+"/eapi/")||!url.getPath().matches("/eapi/(?:user/login|book/search|book/\\d{1,12}/[a-zA-Z0-9]{1,128}(?:/file)?)")||url.getQuery()!=null)throw new IOException("Blocked provider address.");
   HttpURLConnection c=(HttpURLConnection)url.openConnection();connection=c;fresh(generation);c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setUseCaches(false);c.setRequestProperty("Accept",download?"application/octet-stream":"application/json");c.setRequestProperty("User-Agent","ThingsBook/1.12.0");
   try{if(session!=null&&!download){JSONObject cookies=session.getJSONObject("cookies");c.setRequestProperty("remix-userid",cookies.getString("remix_userid"));c.setRequestProperty("remix-userkey",cookies.getString("remix_userkey"));c.setRequestProperty("Cookie","remix_userid="+URLEncoder.encode(cookies.getString("remix_userid"),"UTF-8")+"; remix_userkey="+URLEncoder.encode(cookies.getString("remix_userkey"),"UTF-8"));}
    if(fields!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");byte[] body=fields.getBytes(StandardCharsets.UTF_8);try(OutputStream out=c.getOutputStream()){out.write(body);}finally{Arrays.fill(body,(byte)0);}}
    int status=c.getResponseCode();if(Arrays.asList(301,302,303,307,308).contains(status)){if(!download)throw new IOException("Provider redirected account access. No challenge bypass is attempted.");String target=c.getHeaderField("Location");if(target==null)throw new IOException();value=new URL(url,target).toString();if(!fileAllowed(value))throw new IOException("Unsupported provider download host.");continue;}
    if(status!=200)throw new IOException(status==429?"The provider account limit has been reached.":"Provider unavailable or account access restricted.");int limit=download?MAX:2*1024*1024;if(c.getContentLengthLong()>limit)throw new IOException("Provider response exceeds the allowed size.");
    try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];try{int n;while((n=in.read(b))!=-1){fresh(generation);if(out.size()+n>limit||System.currentTimeMillis()>deadline)throw new IOException("Provider transfer timed out or exceeds the allowed size.");out.write(b,0,n);}fresh(generation);return out.toByteArray();}finally{Arrays.fill(b,(byte)0);}}
   }finally{c.disconnect();if(connection==c)connection=null;}
  }throw new IOException("Too many provider redirects.");
 }
 private static String form(String... fields)throws Exception{StringBuilder b=new StringBuilder();for(int i=0;i<fields.length;i+=2){if(b.length()>0)b.append('&');b.append(URLEncoder.encode(fields[i],"UTF-8")).append('=').append(URLEncoder.encode(fields[i+1],"UTF-8"));}return b.toString();}
 private JSONObject api(String path,String fields,JSONObject session,long generation)throws Exception{byte[] raw=request(DOMAIN+path,fields,session,false,generation);try{JSONObject j=new JSONObject(new String(raw,StandardCharsets.UTF_8));if(j.optInt("success")!=1){String error=j.optString("error").toLowerCase(Locale.ROOT);throw new IOException(error.matches(".*(?:limit|quota).*")?"The provider account download limit has been reached.":error.matches(".*(?:auth|login|session|account).*")?"Sign in again to this provider.":"The provider could not complete this request. Try later; access challenges are not bypassed.");}return j;}finally{Arrays.fill(raw,(byte)0);}}
 JSONObject call(JSONObject v,long dispatchEpoch)throws Exception{
  fresh(dispatchEpoch);
  String action=v.optString("action");if("cancel".equals(action)){cancel();return new JSONObject().put("cancelled",true);}if("logout".equals(action)){synchronized(this){cancel();secrets.delete();}return new JSONObject().put("connected",false);}if("status".equals(action))return new JSONObject().put("connected",session()!=null).put("domain",DOMAIN);
  final long generation;synchronized(this){fresh(dispatchEpoch);if(running)throw new IOException("Finish or cancel the current provider request.");running=true;generation=++epoch;}
  try{if("login".equals(action)){String email=v.optString("email"),password=v.optString("password");if(!email.contains("@")||email.length()>254||password.isEmpty()||password.length()>4096)throw new IOException("Enter a valid email and password.");JSONObject j=api("/eapi/user/login",form("email",email,"password",password),null,generation);fresh(generation);JSONObject user=j.optJSONObject("user");if(user==null)throw new IOException("Unsupported provider session.");JSONObject s=new JSONObject().put("version",1).put("provider","heartleo-zlib-eapi").put("domain",DOMAIN).put("cookies",new JSONObject().put("remix_userid",user.optString("id")).put("remix_userkey",user.optString("remix_userkey",user.optString("remix_user_key"))));save(s,generation);return new JSONObject().put("connected",true).put("domain",DOMAIN);}
   JSONObject s=session();fresh(generation);if(s==null)throw new IOException("Sign in to this provider first.");if("search".equals(action)){String query=v.optString("query");int page=v.optInt("page");if(query.trim().isEmpty()||query.length()>160||page<1||page>1000)throw new IOException("Enter a title, author or ISBN.");JSONObject j=api("/eapi/book/search",form("message",query,"page",String.valueOf(page),"limit","20"),s,generation);fresh(generation);JSONArray input=j.optJSONArray("books"),books=new JSONArray();if(input!=null)for(int i=0;i<Math.min(input.length(),20);i++){JSONObject b=input.optJSONObject(i);if(b==null)continue;String id=b.optString("id"),hash=b.optString("hash"),format=b.optString("extension").toLowerCase(Locale.ROOT);if(!id.matches("\\d{1,12}")||!hash.matches("[a-zA-Z0-9]{1,128}")||!Arrays.asList("epub","pdf","txt").contains(format))continue;books.put(new JSONObject().put("id",id).put("hash",hash).put("title",trim(b.optString("title","Untitled"),300)).put("author",trim(b.optString("author","Unknown author"),300)).put("format",format.toUpperCase(Locale.ROOT)).put("language",trim(b.optString("language"),60)).put("year",trim(b.optString("year"),20)).put("size",trim(b.optString("filesizeString",b.optString("filesize")),40)));}JSONObject pagination=j.optJSONObject("pagination");return new JSONObject().put("page",page).put("more",pagination!=null&&pagination.optInt("total_pages")>page).put("books",books);}
   if("download".equals(action)){JSONObject j=api("/eapi/book/"+reference(v)+"/file",null,s,generation);fresh(generation);JSONObject f=j.optJSONObject("file");String link=f==null?"":f.optString("downloadLink");if(link.isEmpty())link=j.optString("downloadLink",j.optString("url",j.optString("link")));String url=new URL(new URL(DOMAIN),link).toString();if(link.isEmpty()||!fileAllowed(url))throw new IOException("The provider returned a download host not supported by this release.");String ticket=UUID.randomUUID().toString();synchronized(this){fresh(generation);tickets.clear();tickets.put(ticket,new Ticket(url,generation));}return new JSONObject().put("ticket",ticket);}
   throw new IOException("Unknown provider action.");
  }finally{synchronized(this){running=false;}}
 }
 private static String trim(String s,int limit){return s.substring(0,Math.min(s.length(),limit));}
 WebResourceResponse download(String token){Ticket t;synchronized(this){t=tickets.remove(token);if(t==null||t.epoch!=epoch||t.expires<System.currentTimeMillis())return BookCatalog.response(403,"text/plain",new byte[0]);}
  try{return BookCatalog.response(200,"application/octet-stream",request(t.url,null,null,true,t.epoch));}catch(Exception e){return BookCatalog.response(502,"text/plain","Provider download failed or was cancelled. Your library was not changed.".getBytes(StandardCharsets.UTF_8));}
 }
}
